package com.voxel.world;

import org.json.JSONObject;
import org.junit.Test;

import java.io.DataInputStream;
import java.io.File;
import java.io.FileInputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.HashSet;
import java.util.Set;
import java.util.zip.GZIPInputStream;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Guards the bundled Tutorial World against going stale.
 *
 * <p>The map is generated by {@link TutorialWorldAuthor} and exported to
 * {@code src/main/resources/tutorial_world}. When the author changes but the
 * template is not rebuilt, the game happily loads the OLD world — which is how
 * the door overhaul was silently missing from the tutorial for a week. These
 * checks read the shipped chunk files directly and assert the template carries
 * the current author's expectations: doors, every zone's build, the spawn, and
 * a starter kit that can actually be used.</p>
 */
public class TutorialWorldTemplateTest {

    private static final File ROOT = new File("src/main/resources/tutorial_world");
    private static final File OVERWORLD = new File(ROOT, "overworld");
    private static final int G = TutorialWorldGenerator.GROUND;

    @Test
    public void templateUrlExistsAndDeclaresTheTutorial() throws Exception {
        File level = new File(ROOT, "level.dat");
        assertTrue("bundled tutorial level.dat is missing", level.isFile());
        String json;
        try (Reader r = new InputStreamReader(new FileInputStream(level), StandardCharsets.UTF_8)) {
            StringBuilder sb = new StringBuilder();
            char[] buf = new char[4096];
            int n;
            while ((n = r.read(buf)) > 0) sb.append(buf, 0, n);
            json = sb.toString();
        }
        JSONObject root = new JSONObject(json);
        assertTrue("level.dat must mark the save as the tutorial", root.getBoolean("tutorial"));
        assertEquals("survival is the teaching mode", "SURVIVAL", root.getString("gameMode"));
        JSONObject player = root.getJSONObject("player");
        assertEquals("spawn X", 0.5, player.getDouble("x"), 0.001);
        assertEquals("spawn Z", 6.5, player.getDouble("z"), 0.001);
        assertEquals("spawn must stand on the ground", G + 1.0, player.getDouble("y"), 0.001);
        assertTrue("starter kit needs a usable pickaxe", json.contains("stone_pickaxe"));
    }

    @Test
    public void everyZoneHasABuildAndTheCastleHasDoors() throws Exception {
        TutorialWorldAuthor.Zone[] zones = TutorialWorldAuthor.zones();
        Set<Integer> ids = new HashSet<>();
        int[] hits = new int[zones.length];

        int minC = Integer.MAX_VALUE, maxC = Integer.MIN_VALUE;
        for (TutorialWorldAuthor.Zone z : zones) {
            minC = Math.min(minC, z.cx - z.radius - 8);
            maxC = Math.max(maxC, z.cx + z.radius + 8);
        }
        Set<Long> wanted = new HashSet<>();
        for (TutorialWorldAuthor.Zone z : zones) {
            int c0 = (z.cx - z.radius - 8) >> 4;
            int c1 = (z.cx + z.radius + 8) >> 4;
            int d0 = (z.cz - z.radius - 8) >> 4;
            int d1 = (z.cz + z.radius + 8) >> 4;
            for (int cx = c0; cx <= c1; cx++) {
                for (int cz = d0; cz <= d1; cz++) wanted.add(chunkKey(cx, cz));
            }
        }

        int scanned = 0;
        for (File file : chunkFiles()) {
            String name = file.getName().replace(".dat", "");
            String[] parts = name.split("_");
            int cx = Integer.parseInt(parts[0]);
            int cz = Integer.parseInt(parts[1]);
            if (!wanted.contains(chunkKey(cx, cz))) continue;
            scanned++;
            readChunk(file, cx, cz, ids, zones, hits);
        }
        assertTrue("no tutorial chunk files were readable", scanned > 0);

        for (int i = 0; i < zones.length; i++) {
            assertTrue("no authored blocks found for zone '" + zones[i].name + "'", hits[i] > 0);
        }

        // Doors (DecorBlocks 950-969) shipped with the door overhaul; a stale
        // template has none of them and every entrance is a bare hole.
        int doorCount = 0;
        for (int id = 950; id <= 969; id++) if (ids.contains(id)) doorCount++;
        assertTrue("template predates the door overhaul (no door blocks found)", doorCount > 0);
    }

    private static long chunkKey(int cx, int cz) {
        return ((long) cx << 32) ^ (cz & 0xFFFFFFFFL);
    }

    private static Set<File> chunkFiles() {
        Set<File> files = new HashSet<>();
        collect(new File(OVERWORLD, "chunks"), files);
        return files;
    }

    private static void collect(File dir, Set<File> out) {
        File[] children = dir.listFiles();
        if (children == null) return;
        for (File c : children) {
            if (c.isDirectory()) collect(c, out);
            else if (c.getName().endsWith(".dat")) out.add(c);
        }
    }

    private static void readChunk(File file, int cx, int cz, Set<Integer> ids,
                                  TutorialWorldAuthor.Zone[] zones, int[] hits)
            throws Exception {
        try (DataInputStream in = new DataInputStream(
                new GZIPInputStream(new FileInputStream(file)))) {
            int magic = in.readInt();
            if (magic != WorldSaveManager.CHUNK_MAGIC) return;
            in.readInt(); // cx
            in.readInt(); // cz
            int count = in.readInt();
            for (int i = 0; i < count; i++) {
                int idx = in.readUnsignedShort();
                int type = in.readUnsignedShort();
                in.readUnsignedByte();
                ids.add(type);
                int cy = idx >> 12;
                int ly = (idx >> 8) & 15;
                int lx = (idx >> 4) & 15;
                int lz = idx & 15;
                int wx = (cx << 4) + lx;
                int wy = (cy << 4) + ly;
                int wz = (cz << 4) + lz;
                for (int z = 0; z < zones.length; z++) {
                    int dx = wx - zones[z].cx;
                    int dz = wz - zones[z].cz;
                    int r = zones[z].radius;
                    if (dx * dx + dz * dz <= r * r && wy > G) hits[z]++;
                }
            }
        }
    }
}
